# zcube for macOS, one universal (arm64 and x86_64) binary: brew install zigbox/tap/zigcube
#
# Generated by `zig build mac-release` in Zigbox/zigcube from packaging/homebrew/zigcube.rb, which
# holds placeholders for the version, the archive's URL and its SHA-256. It installs the prebuilt
# binary, signed with Developer ID and notarized, from the GitHub release; it does not build from
# source. Nothing here needs sudo: brew writes only under its own prefix.
class Zigcube < Formula
  desc "Command line of Zigcube, the orchestrator for Zigbox workloads"
  homepage "https://github.com/Zigbox/zigcube"
  url "@URL@"
  version "@VERSION@"
  sha256 "@SHA256@"
  license "Apache-2.0"

  # On a Mac the server and the agent run in the zbx virtual machine (they need Linux), so zcube
  # alone is no use there: it comes with the tap's zigbox formula (owner, 2026-11-14).
  depends_on "zigbox/tap/zigbox"
  depends_on :macos

  def install
    bin.install "zcube"
  end

  test do
    # Neither command reaches a server.
    assert_match "zcube #{version}", shell_output("#{bin}/zcube version")
    assert_match "local up", shell_output("#{bin}/zcube help")
  end
end
